static void literalPages(const SceneHdr2PlanCandidate&p){
 for(const auto&f:p.faces){const auto&page=f.page;const auto firstTexel=(f.accumulated->faceIndex()-1)*4;need(f.bytes.size()==size_t(page.width)*page.height*8,"exact GPU fixture page extent");for(size_t y=0;y<page.height;++y)for(size_t x=0;x<page.width;++x)for(size_t k=0;k<8;++k){uint8_t want=page.initialByte;if(x>=page.x&&x<page.x+f.accumulated->width()&&y>=page.y&&y<page.y+f.accumulated->height()){const size_t texel=firstTexel+(y-page.y)*f.accumulated->width()+x-page.x,channel=k/2;const uint16_t word=p.policy.encoding==36?0:(channel==3?0x3c00:(channel==texel%3?0x3800:0));want=uint8_t(word>>((k%2)*8));}need(f.bytes[(y*page.width+x)*8+k]==want,"independent literal HDR2 fixture words");}}
}
